export default {"html":"<h2 id=\"fix\" data-line=\"0\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#fix\" aria-hidden=\"true\"></a> Fix</h2>\n<p data-line=\"2\" class=\"code-line\">Set <code>interactive-widget</code> on <code>&lt;meta name=viewport&gt;</code>.</p>\n<div class=\"code-block-container\"><pre class=\"shiki github-dark\" style=\"background-color:#151e2c;color:#e1e4e8\"><code class=\"code-line\" data-line=\"4\"><span class=\"line\"><span style=\"color:#E1E4E8\">&lt;</span><span style=\"color:#85E89D\">meta</span><span style=\"color:#B392F0\"> name</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"viewport\"</span><span style=\"color:#B392F0\"> content</span><span style=\"color:#E1E4E8\">=</span><span style=\"color:#9ECBFF\">\"width=device-width, initial-scale=1.0, interactive-widget=overlays-content\"</span><span style=\"color:#E1E4E8\">&gt;</span></span>\n<span class=\"line\"></span></code></pre></div><p data-line=\"8\" class=\"code-line\">This matches iOS keyboard behavior, so if your app already works on iOS, you do not need this change. You need it if you branch by platform or designed Android-first.</p>\n<h2 id=\"overview\" data-line=\"10\" class=\"code-line\"><a class=\"header-anchor-link\" href=\"#overview\" aria-hidden=\"true\"></a> Overview</h2>\n<p data-line=\"12\" class=\"code-line\">Starting with Chrome 108, released in November 2022, Android Chrome changes how the layout viewport behaves when the on-screen keyboard appears.</p>\n<p data-line=\"14\" class=\"code-line\"><img src=\"/images/d9b0869e1ebea2/viewport.png\" alt=\"\" class=\"md-img\" loading=\"lazy\"></p>\n<p data-line=\"16\" class=\"code-line\">Units that depend on the viewport such as <code>vw</code> and <code>vh</code>, and DOM positioned with <code>position: fixed; bottom: 0</code>, will behave differently.</p>\n<p data-line=\"18\" class=\"code-line\">See the article below for details on what changes.</p>\n<p data-line=\"20\" class=\"code-line\"><a href=\"https://developer.chrome.com/blog/viewport-resize-behavior/\" rel=\"noopener noreferrer\" target=\"_blank\">https://developer.chrome.com/blog/viewport-resize-behavior/</a><a href=\"https://developer.chrome.com/blog/viewport-resize-behavior/\" style=\"display:none\" target=\"_blank\" rel=\"noopener noreferrer\">https://developer.chrome.com/blog/viewport-resize-behavior/</a></p>\n<p data-line=\"22\" class=\"code-line\">This is important enough that I wrote this post to spread the word, but everything you need is in that article (in English). It is written clearly enough to read through Google Translate if needed—please read the original rather than relying on secondary explanations.</p>\n","headings":[{"id":"fix","text":"Fix","level":2},{"id":"overview","text":"Overview","level":2}]} as const;
